<?php
declare(strict_types=1);
namespace Zoosper\Seo\Contribution;
use Zoosper\Core\Container\ServiceContainer;use Zoosper\Core\Module\ModuleRegistry;use Zoosper\Seo\Contract\{SeoMetadataContributorInterface,SitemapContributorInterface};
final readonly class SeoContributorRegistry{public function __construct(private ModuleRegistry $modules,private ServiceContainer $services){} /** @return list<SeoMetadataContributorInterface> */ public function metadata():array{return $this->collect('metadata',SeoMetadataContributorInterface::class);} /** @return list<SitemapContributorInterface> */ public function sitemap():array{return $this->collect('sitemap',SitemapContributorInterface::class);} private function collect(string $group,string $contract):array{$result=[];foreach($this->modules->enabledModules() as $module){$file=$module->configPath('seo.php');if(!is_file($file))continue;$config=require $file;if(!is_array($config))throw new \RuntimeException('SEO contributor config must return an array: '.$file);foreach(($config[$group]??[]) as $serviceId){if(!is_string($serviceId)||$serviceId==='')continue;$service=$this->services->get($serviceId);if(!$service instanceof $contract)throw new \RuntimeException(sprintf('SEO contributor %s must implement %s.',$serviceId,$contract));$result[]=$service;}}return $result;}}
